extern z_sys_init(void);

/* Read a line with echo support */
static int read_line(char *buf, int size)
{
	int pos = 0;
	char c;

	while (1) {
		if (read(fileno(stdin), &c, 1) != 1)
			return -1;

		if (c == '\r' || c == '\n') {
			printf("\r\n");
			fflush(stdout);
			buf[pos] = '\0';
			return pos;
		}

		if (c == 0x08 || c == 0x7F) { /* Backspace */
			if (pos > 0) {
				pos--;
				printf("\b \b");
				fflush(stdout);
			}
			continue;
		}

		if (pos < size - 1) {
			buf[pos++] = c;
			write(fileno(stdout), &c, 1); /* Echo */
			fflush(stdout);
		}
	}
}

