88	static int bt_app_interface_event_handle(uint16_t type, uint16_t event_id, uint8_t *data, uint16_t data_len)
89	{
90	    bt_app_t *env = bt_app_get_env();
91	
92	    if (type == BT_NOTIFY_COMMON)
93	    {
94	        switch (event_id)
95	        {
96	        case BT_NOTIFY_COMMON_BT_STACK_READY:
97	        {
98	            rt_mb_send(g_bt_app_mb, BT_APP_READY);
99	        }
100	        break;
101	        default:
102	            break;
103	        }
104	    }
105	    else if (type == BT_NOTIFY_A2DP)
106	    {
107	        switch (event_id)
108	        {
109	        case BT_NOTIFY_A2DP_PROFILE_CONNECTED:
110	        {
111	            bt_notify_profile_state_info_t *profile_info = (bt_notify_profile_state_info_t *)data;
112	            if (profile_info->res == BTS2_SUCC)
113	            {
114	                env->addr = profile_info->mac;
115	                env->is_a2dp_connected = 1;
116	            }
117	            LOG_I("A2DP connected");
118	        }
119	        break;
120	        case BT_NOTIFY_A2DP_PROFILE_DISCONNECTED:
121	        {
122	            bt_notify_profile_state_info_t *info = (bt_notify_profile_state_info_t *)data;
123	            env->is_a2dp_connected = 0;
124	            LOG_I("A2DP disconnected %d", info->res);
125	        }
126	        break;
127	        }
128	    }
129	    else if (type == BT_NOTIFY_AVRCP)
130	    {
131	        switch (event_id)
132	        {
133	        case BT_NOTIFY_AVRCP_PROFILE_CONNECTED:
134	        {
135	            LOG_I("AVRCP connected");
136	            bt_notify_profile_state_info_t *profile_info = (bt_notify_profile_state_info_t *)data;
137	            bt_interface_set_avrcp_role_ext(&profile_info->mac, AVRCP_CT);
138	        }
139	        break;
140	        case BT_NOTIFY_AVRCP_PROFILE_DISCONNECTED:
141	        {
142	            bt_notify_profile_state_info_t *info = (bt_notify_profile_state_info_t *)data;
143	            env->is_abs_enabled = 0;
144	            LOG_I("AVRCP disconnected %d", info->res);
145	        }
146	        break;
147	        case BT_NOTIFY_AVRCP_VOLUME_CHANGED_REGISTER:
148	        {
149	            env->is_abs_enabled = 1;
150	        }
151	        break;
152	        case BT_NOTIFY_AVRCP_ABSOLUTE_VOLUME:
153	        {
154	            uint8_t *volume = (uint8_t *)data;
155	#ifdef AUDIO_USING_MANAGER
156	            uint8_t local_vol = bt_interface_avrcp_abs_vol_2_local_vol(*volume, audio_server_get_max_volume());
157	            audio_server_set_private_volume(AUDIO_TYPE_BT_MUSIC, local_vol);
158	#endif
159	        }
160	        break;
161	        default:
162	            break;
163	        }
164	    }
165	
166	    return 0;
167	}
