184	    //__asm("B .");
185	    g_bt_app_mb = rt_mb_create("bt_app", 8, RT_IPC_FLAG_FIFO);
186	    RT_ASSERT(g_bt_app_mb);
187	
188	    bt_interface_register_bt_event_notify_callback(bt_app_interface_event_handle);
