void hci_send_pk_2_controller(uint8_t type, uint16_t length, uint8_t *p_buf, hci_done_cb cb_done)
{
    struct net_buf *buf = NULL;

    switch (type)
    {
    case BT_HCI_H4_CMD:
    {
        uint16_t code = *(p_buf + 1);
        code <<= 8;
        code += *(p_buf);
        buf = bt_hci_cmd_allocate();
        RT_ASSERT(buf);
        bt_buf_set_type(buf, BT_BUF_CMD);
        memcpy(buf->b.data, p_buf, length);
        hl_hci_mark_host_bt(code);
    }
    break;
    case BT_HCI_H4_ACL:
        buf = net_buf_alloc(&bt_acl_pool, K_FOREVER);
        RT_ASSERT(buf);
        bt_buf_set_type(buf, BT_BUF_ACL_OUT);
        break;
    case BT_HCI_H4_SCO:
        buf = net_buf_alloc(&bt_sco_pool, K_FOREVER);
        RT_ASSERT(buf);
        bt_buf_set_type(buf, BT_BUF_SCO_OUT);
        break;
    }
    if (buf)
    {
        net_buf_reserve(buf, BT_BUF_RESERVE);
        memcpy(buf->b.data, p_buf, length);
        net_buf_add(buf, length);
        bt_send(buf);
    }
}

/**
* @brief Filter buf for stack.
*
* @details This function is expected to be called from UART
* interrupt handler (ISR), filter packet for Zephyr BLE stack.
* if it is NOT for Zephyr BLE stack, call the callback of BT stack

__ROM_USED size_t circular_buf_put(struct circular_buf *cb,
                                   const uint8_t     *ptr,
                                   uint16_t           length)
{
    uint16_t size;
    uint32_t wr_mirror;
    uint32_t wr_idx;

    SF_ASSERT(cb != NULL);

    /* whether has enough space */
    size = circular_buf_space_len(cb);

    /* no space */
    if (size == 0)
    {
        return 0;
    }

    /* drop some data */
    if (size < length)
    {
        length = size;
    }

    wr_idx = CB_GET_PTR_IDX(cb->write_idx_mirror);
    wr_mirror = CB_GET_PTR_MIRROR(cb->write_idx_mirror);
    if ((cb->buffer_size - wr_idx) > length)
    {
        /* read_index - write_index = empty space */
        memcpy(&cb->wr_buffer_ptr[wr_idx], ptr, length);
        /* this should not cause overflow because there is enough space for
         * length of data in current mirror */
        wr_idx += length;
        cb->write_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(wr_idx, wr_mirror);
        return length;
    }

    memcpy(&cb->wr_buffer_ptr[wr_idx],
           &ptr[0],
           cb->buffer_size - wr_idx);
    memcpy(&cb->wr_buffer_ptr[0],
           &ptr[cb->buffer_size - wr_idx],
           length - (cb->buffer_size - wr_idx));

    /* we are going into the other side of the mirror */
    wr_mirror = ~wr_mirror;
    wr_idx = length - (cb->buffer_size - wr_idx);
    cb->write_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(wr_idx, wr_mirror);

    return length;
}

