381	static void rx_thread(void *p1, void *p2, void *p3)
382	{
383	    const struct device *dev = p1;
384	    struct h4_config *cfg = h4_cfg(dev);
385	    struct h4_data *h4 = dev->user_data;
386	    struct net_buf *buf;
387	
388	    while (1)
389	    {
390	        rt_sem_take(&(cfg->sem), RT_WAITING_FOREVER);
391	        while (ipc_queue_get_rx_size(mbox_env.ipc_port))
392	        {
393	            struct h4_data *h4 = h4_mbox_device.user_data;
394	            struct net_buf *buf;
395	            process_rx((const struct rt_device *)&h4_mbox_device);
396	            buf = k_fifo_get(&h4->rx.fifo, K_FOREVER);
397	            while (buf)
398	            {
399	                LOG_DBG("Calling bt_recv(%p),len=%d,data=%p", buf, buf->len, buf->data);
400	
401	                if (buf->len && buf->data)
402	                    log_hci_to_console(buf);
403	                else
404	                    break;
405	
406	                if (ble_stack_filter(buf))
407	                {
408	                    if (h4->recv)
409	                        h4->recv(&h4_mbox_device, buf);
410	                    else
411	                        net_buf_unref(buf);
412	                }
413	                buf = k_fifo_get(&h4->rx.fifo, K_NO_WAIT);
414	            };
415	        }
416	        process_tx((const struct rt_device *)&h4_mbox_device);
417	    }
418	}
