377	static int h4_open(const struct device *dev, bt_hci_recv_t recv, void *hci_data)
378	{
379		int ret;
380		struct h4_data *h4 = dev->data;
381		char dev_name[32];
382	
383		if (dev->name == NULL) {
384			LOG_ERR("No device name");
385			return -EINVAL;
386		}
387	
388		ret = snprintf(dev_name, sizeof(dev_name), "%s", dev->name);
389		if (ret < 0 || ret >= sizeof(dev_name)) {
390			LOG_ERR("dev_name:%s snprintf failed, ret %d, ", dev->name, ret);
391			return -EINVAL;
392		}
393	
394		ret = open(dev_name, O_RDWR | O_BINARY | O_CLOEXEC);
395		if (ret < 0) {
396			goto bail;
397		}
398	
399		h4->fd = ret;
400		syslog(LOG_INFO, "H4: %s opened as fd %d\n", dev_name, h4->fd);
401	
402		ret = (int)k_thread_create(&h4->rx_thread_data, h4->rx_thread_stack,
403					   K_THREAD_STACK_SIZEOF(h4->rx_thread_stack), h4_rx_thread, (void *)dev, NULL,
404					   NULL, K_PRIO_COOP(CONFIG_BT_RX_PRIO), 0, K_NO_WAIT);
405	
406		if (ret < 0) {
407			goto bail;
408		} else {
409			ret = 0;
410		}
411	
412		h4->recv = recv;
413		h4->hci_data = hci_data;
414	
415		ret = snprintf(dev_name, sizeof(dev_name), "BT Driver %s", dev->name);
416		if (ret < 0 || ret >= sizeof(dev_name)) {
417			LOG_ERR("dev_name:%s snprintf failed, ret %d, ", dev->name, ret);
418			return -EINVAL;
419		}
420	
421		k_thread_name_set(&h4->rx_thread_data, dev_name);
422		LOG_DBG("returning");
423	
424		return 0;
425	
426	bail:
427		close(h4->fd);
428		h4->fd = -1;
429	
430		return ret;
431	}
